 34→
 35→const PAGE_SIZE = 10;
 36→const ADMIN_SHOP = "zip-code-checker.myshopify.com";
 37→const MAX_REQUESTS_PER_SHOP = 20;
 38→const MAX_DESCRIPTION_LENGTH = 2000;
