154→function formatDate(d: string | Date): string {
155→  return new Date(d).toLocaleDateString("en-US", {
156→    month: "short",
157→    day: "numeric",
158→    year: "numeric",
159→  });
160→}
161→
162→function truncateText(text: string, maxChars: number): string {
163→  if (text.length <= maxChars) return text;
164→  return text.slice(0, maxChars).trimEnd() + "\u2026";
