203→// ---------------------------------------------------------------------------
204→// Action
205→// ---------------------------------------------------------------------------
206→
207→export const action = async ({
208→  request,
209→}: ActionFunctionArgs): Promise<ActionResult> => {
210→  const { session } = await authenticate.admin(request);
211→  const shop = session.shop;
212→  const isAdmin = shop === ADMIN_SHOP;
213→  const formData = await request.formData();
214→  const intent = String(formData.get("intent") ?? "");
215→
216→  try {
217→    switch (intent) {
218→      case "submit": {
219→        const title = String(formData.get("title") ?? "").trim();
220→        const description = String(formData.get("description") ?? "").trim();
221→        const rawCategory = String(formData.get("category") ?? "General").trim();
222→        const category = VALID_CATEGORIES.has(rawCategory) ? rawCategory : "General";
223→
224→        if (!title || !description) {
225→          return { error: "Title and description are required." };
226→        }
227→        if (title.length > 150) {
228→          return { error: "Title must be 150 characters or fewer." };
229→        }
230→        if (description.length > MAX_DESCRIPTION_LENGTH) {
231→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
232→        }
233→
234→        // Per-shop submission limit
235→        const existingCount = await db.featureRequest.count({ where: { shop } });
236→        if (existingCount >= MAX_REQUESTS_PER_SHOP) {
237→          return { error: `You can submit up to ${MAX_REQUESTS_PER_SHOP} feature requests. Delete an existing one to submit a new one.` };
238→        }
239→
240→        await db.featureRequest.create({
241→          data: { title, description, category, shop },
242→        });
243→
244→        return { success: true, intent: "submit" };
245→      }
246→
247→      case "vote": {
248→        const featureId = String(formData.get("featureId") ?? "").trim();
249→        if (!featureId) return { error: "Feature ID is required." };
250→
251→        const feature = await db.featureRequest.findUnique({
252→          where: { id: featureId },
253→        });
254→        if (!feature) return { error: "Feature request not found." };
255→
256→        const existing = await db.featureVote.findUnique({
257→          where: {
258→            featureRequestId_shop: { featureRequestId: featureId, shop },
259→          },
260→        });
261→
262→        let voted: boolean;
263→
264→        if (existing) {
265→          await db.featureVote.delete({ where: { id: existing.id } });
266→          // Atomic decrement
267→          const updated = await db.featureRequest.update({
268→            where: { id: featureId },
269→            data: { votesCount: { decrement: 1 } },
270→          });
271→          // Ensure count doesn't go below 0
272→          if (updated.votesCount < 0) {
273→            await db.featureRequest.update({
274→              where: { id: featureId },
275→              data: { votesCount: 0 },
276→            });
277→          }
278→          voted = false;
279→          const finalCount = Math.max(0, updated.votesCount);
280→          return { success: true, intent: "vote", featureId, newCount: finalCount, voted };
281→        } else {
282→          await db.featureVote.create({
283→            data: { featureRequestId: featureId, shop },
284→          });
285→          // Atomic increment
286→          const updated = await db.featureRequest.update({
287→            where: { id: featureId },
288→            data: { votesCount: { increment: 1 } },
289→          });
290→          voted = true;
291→          return { success: true, intent: "vote", featureId, newCount: updated.votesCount, voted };
292→        }
293→      }
294→
295→      case "delete": {
296→        const deleteId = String(formData.get("id") ?? "").trim();
297→        if (!deleteId) return { error: "Feature ID is required." };
298→
299→        const toDelete = await db.featureRequest.findUnique({

300→          where: { id: deleteId },
301→        });
302→        if (!toDelete) return { error: "Feature request not found." };
303→
304→        // Admin can delete any, regular users only their own
305→        if (!isAdmin && toDelete.shop !== shop) {
306→          return { error: "You can only delete your own feature requests." };
307→        }
308→
309→        await db.featureRequest.delete({ where: { id: deleteId } });
310→        return { success: true, intent: "delete" };
311→      }
312→
313→      case "edit": {
314→        const editId = String(formData.get("id") ?? "").trim();
315→        const editTitle = String(formData.get("title") ?? "").trim();
316→        const editDescription = String(formData.get("description") ?? "").trim();
317→        const rawEditCategory = String(formData.get("category") ?? "General").trim();
318→        const editCategory = VALID_CATEGORIES.has(rawEditCategory) ? rawEditCategory : "General";
319→
320→        if (!editId) return { error: "Feature ID is required." };
321→        if (!editTitle || !editDescription) {
322→          return { error: "Title and description are required." };
323→        }
324→        if (editTitle.length > 150) {
325→          return { error: "Title must be 150 characters or fewer." };
326→        }
327→        if (editDescription.length > MAX_DESCRIPTION_LENGTH) {
328→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
329→        }
330→
331→        const toEdit = await db.featureRequest.findUnique({ where: { id: editId } });
332→        if (!toEdit) return { error: "Feature request not found." };
333→
334→        if (!isAdmin && toEdit.shop !== shop) {
335→          return { error: "You can only edit your own feature requests." };
336→        }
337→
338→        await db.featureRequest.update({
339→          where: { id: editId },
340→          data: { title: editTitle, description: editDescription, category: editCategory },
341→        });
342→
343→        return { success: true, intent: "edit" };
344→      }
345→
346→      case "update-status": {
347→        if (!isAdmin) {
348→          return { error: "Only the app admin can change request statuses." };
349→        }
350→
351→        const statusId = String(formData.get("id") ?? "").trim();
352→        const newStatus = String(formData.get("status") ?? "").trim();
353→
354→        if (!statusId) return { error: "Feature ID is required." };
355→        if (!VALID_STATUSES.has(newStatus)) {
356→          return { error: "Invalid status value." };
357→        }
358→
359→        const toUpdate = await db.featureRequest.findUnique({
360→          where: { id: statusId },
361→        });
362→        if (!toUpdate) return { error: "Feature request not found." };
363→
364→        await db.featureRequest.update({
365→          where: { id: statusId },
366→          data: { status: newStatus },
367→        });
368→
369→        return { success: true, intent: "update-status" };
370→      }
371→
372→      default:
373→        return { error: "Unknown action." };
374→    }
375→  } catch (err) {
376→    const message =
377→      err instanceof Error ? err.message : "An unexpected error occurred.";
378→    return { error: message };
379→  }
380→};
