382→// ---------------------------------------------------------------------------
383→// Component
384→// ---------------------------------------------------------------------------
385→
386→export default function FeatureRequestsPage() {
387→  const {
388→    features: rawFeatures,
389→    votedIds: initialVotedIds,
390→    shop,
391→    stats,
392→    isAdmin,
393→  } = useLoaderData<typeof loader>();
394→
395→  // Separate fetchers for independent actions
396→  const voteFetcher = useFetcher<typeof action>();
397→  const deleteFetcher = useFetcher<typeof action>();
398→  const submitFetcher = useFetcher<typeof action>();
399→  const statusFetcher = useFetcher<typeof action>();
400→  const editFetcher = useFetcher<typeof action>();
401→
402→  const shopify = useAppBridge();
403→  const navigate = useNavigate();
404→
405→  // ------------------------------------------------------------------
406→  // Local state — optimistic votes
407→  // ------------------------------------------------------------------
408→  const [optimisticVotes, setOptimisticVotes] = useState<
409→    Map<string, { count: number; voted: boolean }>
410→  >(() => new Map());
411→  const [votedIds, setVotedIds] = useState<Set<string>>(
412→    () => new Set(initialVotedIds),
413→  );
414→
415→  // Per-card loading indicators
416→  const [pendingVoteId, setPendingVoteId] = useState<string | null>(null);
417→  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
418→
419→  // ------------------------------------------------------------------
420→  // UI state
421→  // ------------------------------------------------------------------
422→  const [selectedTab, setSelectedTab] = useState(0);
423→  const [sortValue, setSortValue] = useState("votes");
424→  const [currentPage, setCurrentPage] = useState(1);
425→  const [modalOpen, setModalOpen] = useState(false);
426→  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
427→  const [modalError, setModalError] = useState<string | null>(null);
428→  const [searchQuery, setSearchQuery] = useState("");
429→
430→  // Form state
431→  const [newTitle, setNewTitle] = useState("");
432→  const [newDescription, setNewDescription] = useState("");
433→  const [newCategory, setNewCategory] = useState("General");
434→
435→  // Delete confirmation state
436→  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
437→
438→  // Edit modal state
439→  const [editModalOpen, setEditModalOpen] = useState(false);
440→  const [editId, setEditId] = useState("");
441→  const [editTitle, setEditTitle] = useState("");
442→  const [editDescription, setEditDescription] = useState("");
443→  const [editCategory, setEditCategory] = useState("General");
444→  const [editModalError, setEditModalError] = useState<string | null>(null);
445→
446→  // ------------------------------------------------------------------
447→  // Resolve optimistic state into features list
448→  // ------------------------------------------------------------------
449→  const features = useMemo<FeatureRequestRecord[]>(() => {

450→    return (rawFeatures as FeatureRequestRecord[]).map((f) => {
451→      const opt = optimisticVotes.get(f.id);
452→      if (opt) return { ...f, votesCount: opt.count };
453→      return f;
454→    });
455→  }, [rawFeatures, optimisticVotes]);
456→
457→  // ------------------------------------------------------------------
458→  // Handle vote fetcher responses
459→  // ------------------------------------------------------------------
460→  useEffect(() => {
461→    if (voteFetcher.state !== "idle" || !voteFetcher.data) return;
462→    const data = voteFetcher.data;
463→
464→    if ("error" in data) {
465→      shopify.toast.show(data.error, { isError: true });
466→      setPendingVoteId(null);
467→      return;
468→    }
469→
470→    if ("success" in data && data.success && data.intent === "vote") {
471→      const voteData = data as VoteResult;
472→      setOptimisticVotes((prev) => {
473→        const next = new Map(prev);
474→        next.set(voteData.featureId, {
475→          count: voteData.newCount,
476→          voted: voteData.voted,
477→        });
478→        return next;
479→      });
480→      setVotedIds((prev) => {
481→        const next = new Set(prev);
482→        if (voteData.voted) next.add(voteData.featureId);
483→        else next.delete(voteData.featureId);
484→        return next;
485→      });
486→      setPendingVoteId(null);
487→    }
488→  }, [voteFetcher.state, voteFetcher.data, shopify]);
489→
490→  // ------------------------------------------------------------------
491→  // Handle delete fetcher responses
492→  // ------------------------------------------------------------------
493→  useEffect(() => {
494→    if (deleteFetcher.state !== "idle" || !deleteFetcher.data) return;
495→    const data = deleteFetcher.data;
496→
497→    if ("error" in data) {
498→      shopify.toast.show(data.error, { isError: true });
499→      setPendingDeleteId(null);
500→      return;
501→    }
502→
503→    if ("success" in data && data.success && data.intent === "delete") {
504→      shopify.toast.show("Feature request deleted.");
505→      setPendingDeleteId(null);
506→      setConfirmDeleteId(null);
507→    }
508→  }, [deleteFetcher.state, deleteFetcher.data, shopify]);
509→
510→  // ------------------------------------------------------------------
511→  // Handle submit fetcher responses
512→  // ------------------------------------------------------------------
513→  useEffect(() => {
514→    if (submitFetcher.state !== "idle" || !submitFetcher.data) return;
515→    const data = submitFetcher.data;
516→
517→    if ("error" in data) {
518→      setModalError(data.error);
519→      return;
520→    }
521→
522→    if ("success" in data && data.success && data.intent === "submit") {
523→      shopify.toast.show("Feature request submitted! Thank you.");
524→      setModalOpen(false);
525→      setNewTitle("");
526→      setNewDescription("");
527→      setNewCategory("General");
528→      setModalError(null);
529→      // Bring the new request into view: switch to All tab, sort by Newest, page 1
530→      setSelectedTab(0);
531→      setSortValue("newest");
532→      setCurrentPage(1);
533→    }
534→  }, [submitFetcher.state, submitFetcher.data, shopify]);
535→
536→  // ------------------------------------------------------------------
537→  // Handle status fetcher responses
538→  // ------------------------------------------------------------------
539→  useEffect(() => {
540→    if (statusFetcher.state !== "idle" || !statusFetcher.data) return;
541→    const data = statusFetcher.data;
542→
543→    if ("error" in data) {
544→      shopify.toast.show(data.error, { isError: true });
545→      return;
546→    }
547→
548→    if ("success" in data && data.success && data.intent === "update-status") {
549→      shopify.toast.show("Status updated.");
550→    }
551→  }, [statusFetcher.state, statusFetcher.data, shopify]);
552→
553→  // ------------------------------------------------------------------
554→  // Handle edit fetcher responses
555→  // ------------------------------------------------------------------
556→  useEffect(() => {
557→    if (editFetcher.state !== "idle" || !editFetcher.data) return;
558→    const data = editFetcher.data;
559→
560→    if ("error" in data) {
561→      setEditModalError(data.error);
562→      return;
563→    }
564→
565→    if ("success" in data && data.success && data.intent === "edit") {
566→      shopify.toast.show("Feature request updated.");
567→      setEditModalOpen(false);
568→      setEditId("");
569→      setEditTitle("");
570→      setEditDescription("");
571→      setEditCategory("General");
572→      setEditModalError(null);
573→    }
574→  }, [editFetcher.state, editFetcher.data, shopify]);
575→
576→  // ------------------------------------------------------------------
577→  // Filter + sort
578→  // ------------------------------------------------------------------
579→  const tabFilter: TabFilter = TAB_FILTERS[selectedTab] ?? "all";
580→
581→  const filteredFeatures = useMemo(() => {
582→    let list = features;
583→
584→    if (tabFilter !== "all") {
585→      if (tabFilter === "done") {
586→        list = list.filter(
587→          (f) => f.status === "done" || f.status === "shipped",
588→        );
589→      } else {
590→        list = list.filter((f) => f.status === tabFilter);
591→      }
592→    }
593→
594→    // Apply search filter (client-side, case-insensitive)
595→    if (searchQuery.trim()) {
596→      const q = searchQuery.trim().toLowerCase();
597→      list = list.filter(
598→        (f) =>
599→          f.title.toLowerCase().includes(q) ||

600→          f.description.toLowerCase().includes(q),
601→      );
602→    }
603→
604→    return [...list].sort((a, b) => {
605→      if (sortValue === "votes") return b.votesCount - a.votesCount;
606→      if (sortValue === "newest")
607→        return (
608→          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
609→        );
610→      if (sortValue === "oldest")
611→        return (
612→          new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
613→        );
614→      return 0;
615→    });
616→  }, [features, tabFilter, sortValue, searchQuery]);
617→
618→  const totalPages = Math.max(
619→    1,
620→    Math.ceil(filteredFeatures.length / PAGE_SIZE),
621→  );
622→  const paginatedFeatures = useMemo(() => {
623→    const start = (currentPage - 1) * PAGE_SIZE;
624→    return filteredFeatures.slice(start, start + PAGE_SIZE);
625→  }, [filteredFeatures, currentPage]);
626→
627→  // ------------------------------------------------------------------
628→  // Handlers
629→  // ------------------------------------------------------------------
630→  const handleTabChange = useCallback((tabIndex: number) => {
631→    setSelectedTab(tabIndex);
632→    setCurrentPage(1);
633→    setSearchQuery("");
634→  }, []);
635→
636→  const handleSortChange = useCallback((val: string) => {
637→    setSortValue(val);
638→    setCurrentPage(1);
639→  }, []);
640→
641→  const handleSearchChange = useCallback((val: string) => {
642→    setSearchQuery(val);
643→    setCurrentPage(1);
644→  }, []);
645→
646→  const handleVote = useCallback(
647→    (featureId: string) => {
648→      const feature = features.find((f) => f.id === featureId);
649→      if (!feature) return;
650→
651→      const currentlyVoted = votedIds.has(featureId);
652→      const currentCount =
653→        optimisticVotes.get(featureId)?.count ?? feature.votesCount;
654→
655→      // Optimistic update
656→      setOptimisticVotes((prev) => {
657→        const next = new Map(prev);
658→        next.set(featureId, {
659→          count: currentlyVoted
660→            ? Math.max(0, currentCount - 1)
661→            : currentCount + 1,
662→          voted: !currentlyVoted,
663→        });
664→        return next;
665→      });
666→      setVotedIds((prev) => {
667→        const next = new Set(prev);
668→        if (currentlyVoted) next.delete(featureId);
669→        else next.add(featureId);
670→        return next;
671→      });
672→
673→      setPendingVoteId(featureId);
